#!/usr/bin/env sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Generated by build.py from recipe.yml for recipe pop3-limit-a-mailbox-to-imap. Do not edit.
set -e
cd "$(dirname "$0")"
cat > order.eml <<'EOF'
From: shop@example.com
To: ann@example.com
Subject: Order 1042 shipped

Your order is on its way.
EOF
cat > wait-for-log.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Waits, at most ten seconds, until the log holds <count> lines with <text>, then prints them
# without their exchange numbers. Exit 1 if they never come.
# Usage: sh wait-for-log.sh <text> <count> <log file>
tries=0
until [ "$(grep -c -F -- "$1" "$3")" -ge "$2" ]; do
  tries=$((tries + 1))
  [ "$tries" -ge 10 ] && exit 1
  sleep 1
done
grep -F -- "$1" "$3" | sed 's/^#[0-9]* //'
EOF
surl -v --log-file surl.log --mail-domain example.com --mailbox "ann@example.com:annpass;protocols=imap" --mailbox bob@example.com:bobpass --mailbox shop@example.com:shoppass smtp://127.0.0.1:8080/ imap://127.0.0.1:8081/ pop3://127.0.0.1:8082/ &
sleep 1
curl -sS --crlf -u shop@example.com:shoppass --mail-from shop@example.com --mail-rcpt ann@example.com -T order.eml smtp://127.0.0.1:8080/shop.example.com
curl -sS -o /dev/null --retry 10 --retry-all-errors --retry-delay 1 -u ann@example.com:annpass -X "FETCH 1 FLAGS" imap://127.0.0.1:8081/INBOX
curl -sS -u ann@example.com:annpass pop3://127.0.0.1:8082/ || true
kill $(jobs -p)
